INSERT INTO `onl_cgform_enhance_js` VALUES ('097cbc943f9ad4b4c04f0d0073c104e9', 'onlChange(){\n   return {\n     //网关变更时触发\n     gateway_code(){\n      let gateway_codevalue = event.value==null?\'\':event.value\n      let values = {\'module_id\':gateway_codevalue+event.row.meter_id}\n       that.triggleChangeValues(values)\n    }\n     meter_id(){//表号变更时触发\n      let meter_idvalue = event.value==null?\'\':event.value\n      let values2 = {\'module_id\':event.row.gateway_code+meter_idvalue}\n      that.triggleChangeValues(values2)\n    }\n     \n     \n\n     \n  }\n }', 'form', null, '402881d89454e9a6019454e9afd00005');
INSERT INTO `onl_cgform_enhance_js` VALUES ('0b326acbbc8e52c9c9ecdb19342fc3cf', 'show(){\n   console.log(\'form\',that)\n   //this.form.setFieldsValue({\"name\":\"name值\"})  \n  that.$nextTick(() => {\n           //age是对应表的字段名\n            that.form.setFieldsValue({\"age\":\"999\"})\n          });\n}\n\nonlChange(){\n   return {\n     \n     sex(){\n        let value = event.value\n        //alert(\'触发控件\',value)\n        \n         //性别改动，年龄归零\n        if(value!=null && value!=\"\"){   \n          let values = {\'age\':0}\n          that.triggleChangeValues(values)\n        }\n      }\n     \n    }\n }\n', 'form', null, '05a3a30dada7411c9109306aa4117068');
