INSERT INTO `onl_cgform_enhance_js` VALUES ('47c75074f0332a39cf67a20a0ec5163a', 'onlChange(){\n   return {\n    gateway_id(){\n      let gateway_idvalue = event.value\n      let building_idvalue=\'\'\n      if(event.row.building_id==undefined||event.row.building_id==null){\n      let building_idvalue=\'\'\n      let values1 = {\'gateway_code\':gateway_idvalue+building_idvalue}\n       that.triggleChangeValues(values1)\n     // console.log(\'hhr3=\'+building_idvalue)\n    }else{\n     let building_idvalue=event.row.building_id==null?\'\':event.row.building_id\n     let values1 = {\'gateway_code\':gateway_idvalue+building_idvalue}\n       that.triggleChangeValues(values1)\n    // console.log(\'gateway_idvalue2=\'+gateway_idvalue)\n    // console.log(\'hhr2=\'+building_idvalue)\n}\n     // console.log(\'hhr\'+JSON.stringify(event.row.building_id))\n    }\n     building_id(){\n      let building_idvalue = event.value==null?\'\':event.value\n      let values2 = {\'gateway_code\':event.row.gateway_id+building_idvalue}\n       that.triggleChangeValues(values2)\n    }\n     \n  }\n }', 'form', null, '12164adca1f14e5fbc0d3d8c92d0f070');
INSERT INTO `onl_cgform_enhance_js` VALUES ('5e9ccc1e2b977bdd5a873a6bd6311290', 'jihuo_hook(){\n  console.log(\'当前选中行的id\', this);\n  console.log(\'this.abc\', this.abc);\n   import {useMessage} from \"@/hooks/useMessage\"\n        const {createMessage} = useMessage()\n        function sayHi () {\n            createMessage.success(\"这是代码里的提示：hello world!\")\n        }\n        sayHi();\n}\n\n\n\ntest1(){\n  this.openCustomModal({\n    title: \'测试自定义弹框1\',\n    width: 800,\n     hide: [\'cc\']\n  });\n}\n\nsetup(){\n    console.log(\"进入form: \",this)\n    import { defineComponent, computed, CSSProperties, unref, ref, watchEffect, watch, PropType } from \'vue\';\n  \n  watch(name,(newValue,oldValue)=>{\n    console.log(\"新值是\"+newValue, \"旧址是\"+oldValue);\n  })\n  \n}', 'list', null, '9ab817fd4c2e4e7ba6652c4fa46af389');
INSERT INTO `onl_cgform_enhance_js` VALUES ('6dd82d8eac166627302230a809233481', 'ces_order_goods_onlChange(){\n    return {\n        num(){\n           \n            let id = event.row.id\n            let num = event.row.num\n            let price = event.row.price\n\n            let targrt = event.target\n            \n            let nval = price*num\n            console.log(\'row\',event.row);\n            console.log(\'num\',num);\n            console.log(\'that\',that);\n            let otherValues = {\'zong_price\': nval}\n              \n            that.triggleChangeValues(otherValues,id,targrt)\n   \n\n        }\n    }\n}', 'form', null, '56efb74326e74064b60933f6f8af30ea');
INSERT INTO `onl_cgform_enhance_js` VALUES ('73ff4666e0cf5c2070263345e1e11835', 'one(){\n  console.log(\'当前选中行的id\', this.selectedRowKeys);\n}\n\nbeforeDelete(row){\n  return new Promise(resolve=>{\n    console.log(\'删除数据之前看看数据\', row);\n    resolve();\n  });\n}', 'list', null, '553a4172fde446419cb602dc70f9ee67');
